  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Academic Settings - Stores current academic year and semester type\nmodel AcademicSettings {\n  id                  Int      @id @default(autoincrement())\n  academicYear        String   @map(\"academic_year\") @db.VarChar(20)\n  currentSemesterType String   @map(\"current_semester_type\") @db.VarChar(10) // ODD or EVEN\n  createdAt           DateTime @default(now()) @map(\"created_at\")\n  updatedAt           DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"academic_settings\")\n}\n\n// Semester - Stores all available semesters\nmodel Semester {\n  id             Int      @id @default(autoincrement())\n  semesterNumber Int      @unique @map(\"semester_number\") // 1, 2, 3, 4, 5, 6, 7, 8\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  sections   Section[]\n  subjects   Subject[]\n  timetables Timetable[]\n\n  @@map(\"semesters\")\n}\n\n// Section - Stores sections for each semester\nmodel Section {\n  id          Int      @id @default(autoincrement())\n  semesterId  Int      @map(\"semester_id\")\n  sectionName String   @map(\"section_name\") @db.VarChar(10) // A, B, C, D\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  semester   Semester    @relation(fields: [semesterId], references: [id], onDelete: Cascade)\n  students   Student[]\n  timetables Timetable[]\n\n  @@unique([semesterId, sectionName])\n  @@index([semesterId])\n  @@map(\"sections\")\n}\n\n// Faculty - Stores faculty information\nmodel Faculty {\n  id        Int      @id @default(autoincrement())\n  name      String   @db.VarChar(100)\n  email     String   @unique @db.VarChar(100)\n  password  String   @db.VarChar(255)\n  role      String   @default(\"FACULTY\") @db.VarChar(20) // HOD, FACULTY\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  subjectFaculties SubjectFaculty[]\n  timetables       Timetable[]\n\n  @@index([email])\n  @@map(\"faculties\")\n}\n\n// Subject - Stores subjects for each semester\nmodel Subject {\n  id          Int      @id @default(autoincrement())\n  subjectName String   @map(\"subject_name\") @db.VarChar(100)\n  subjectCode String   @unique @map(\"subject_code\") @db.VarChar(20)\n  semesterId  Int      @map(\"semester_id\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  semester         Semester         @relation(fields: [semesterId], references: [id], onDelete: Cascade)\n  subjectFaculties SubjectFaculty[]\n  timetables       Timetable[]\n\n  @@index([semesterId])\n  @@map(\"subjects\")\n}\n\n// SubjectFaculty - Mapping between subjects and faculty\nmodel SubjectFaculty {\n  id        Int      @id @default(autoincrement())\n  subjectId Int      @map(\"subject_id\")\n  facultyId Int      @map(\"faculty_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  faculty Faculty @relation(fields: [facultyId], references: [id], onDelete: Cascade)\n\n  @@unique([subjectId, facultyId])\n  @@index([subjectId])\n  @@index([facultyId])\n  @@map(\"subject_faculties\")\n}\n\n// Student - Stores student information\nmodel Student {\n  id         Int      @id @default(autoincrement())\n  usn        String   @unique @db.VarChar(20)\n  name       String   @db.VarChar(100)\n  phone      String   @db.VarChar(15)\n  email      String   @unique @db.VarChar(100)\n  semesterId Int      @map(\"semester_id\")\n  sectionId  Int      @map(\"section_id\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  section     Section      @relation(fields: [sectionId], references: [id], onDelete: Cascade)\n  attendance  Attendance?\n  performance Performance?\n\n  @@index([semesterId])\n  @@index([sectionId])\n  @@index([usn])\n  @@map(\"students\")\n}\n\n// Timetable - Stores timetable for each section (uploaded by Faculty Portal)\nmodel Timetable {\n  id         Int      @id @default(autoincrement())\n  day        String   @db.VarChar(20) // Monday, Tuesday, etc.\n  period     Int // 1, 2, 3, 4, 5, etc.\n  subjectId  Int      @map(\"subject_id\")\n  facultyId  Int      @map(\"faculty_id\")\n  semesterId Int      @map(\"semester_id\")\n  sectionId  Int      @map(\"section_id\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  subject  Subject  @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n  faculty  Faculty  @relation(fields: [facultyId], references: [id], onDelete: Cascade)\n  semester Semester @relation(fields: [semesterId], references: [id], onDelete: Cascade)\n  section  Section  @relation(fields: [sectionId], references: [id], onDelete: Cascade)\n\n  @@unique([day, period, semesterId, sectionId])\n  @@index([semesterId, sectionId])\n  @@map(\"timetables\")\n}\n\n// Attendance - Stores attendance percentage (managed by Team-3)\nmodel Attendance {\n  id                   Int      @id @default(autoincrement())\n  studentId            Int      @unique @map(\"student_id\")\n  attendancePercentage Float    @map(\"attendance_percentage\") @db.DoublePrecision\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n  updatedAt            DateTime @updatedAt @map(\"updated_at\")\n\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@index([studentId])\n  @@map(\"attendances\")\n}\n\n// Performance - Stores performance percentage (managed by Team-3)\nmodel Performance {\n  id                    Int      @id @default(autoincrement())\n  studentId             Int      @unique @map(\"student_id\")\n  performancePercentage Float    @map(\"performance_percentage\") @db.DoublePrecision\n  createdAt             DateTime @default(now()) @map(\"created_at\")\n  updatedAt             DateTime @updatedAt @map(\"updated_at\")\n\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@index([studentId])\n  @@map(\"performances\")\n}\n",
